package com.pathstudy.assessment.domain;
import com.pathstudy.curriculum.domain.*; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal;
@Entity @Table(name="question_objective_alignments", uniqueConstraints=@UniqueConstraint(name="uk_question_objective_alignment",columnNames={"question_version_id","learning_objective_id"}), indexes={@Index(name="idx_question_objective_question",columnList="question_version_id"),@Index(name="idx_question_objective_objective",columnList="learning_objective_id")})
@Getter @Setter @NoArgsConstructor public class QuestionObjectiveAlignment extends AuditedEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="question_version_id",nullable=false) private QuestionVersion questionVersion; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="learning_objective_id",nullable=false) private LearningObjective learningObjective; @Column(nullable=false,precision=8,scale=4) private BigDecimal measurementWeight=BigDecimal.ONE; @Column(nullable=false,precision=8,scale=4) private BigDecimal evidenceStrength=BigDecimal.ONE; @Enumerated(EnumType.STRING) @Column(length=16) private CognitiveLevel cognitiveLevel; }
